mapper.select:
select t.id as id, concat( coalesce(nullif(trim(t.team_name), ''), concat('球队#', t.id)), case when t.short_name is null or trim(t.short_name) = '' then '' else concat(' · ', t.short_name) end ) as label, concat( coalesce(nullif(trim(s.series_name), ''), '赛事'), ' · ', coalesce(nullif(trim(se.display_title), ''), se.season_name), ' · ', coalesce(nullif(trim(d.division_name), ''), '未分赛区'), ' · ', coalesce(nullif(trim(d.platform_code), ''), '-'), '/',
) as secondaryLabel, cast(t.team_status as char) as status, null as memberId, t.id as teamId, null as eventTeamId, null as eventPlayerId, t.team_name as teamName, t.team_no as playerNo, t.short_name as gameId, d.division_name as divisionName, d.platform_code as platformCode, d.game_mode as gameMode from basket_team t inner join basket_division d on d.id = t.division_id and d.is_delete = 0 inner join basket_season se on se.id = d.season_id and se.is_delete = 0 left join basket_series s on s.id = se.series_id and s.is_delete = 0 where t.is_delete = 0 and d.season_id = #{seasonId}
and ( t.team_name like concat('%', #{keyword}, '%') or t.short_name like concat('%', #{keyword}, '%') or t.team_no like concat('%', #{keyword}, '%') or t.english_name like concat('%', #{keyword}, '%') or d.division_name like concat('%', #{keyword}, '%') or d.platform_code like concat('%', #{keyword}, '%') )
order by d.sort_order asc, d.id asc, t.team_name asc, t.id asc

select et.id as id, concat( coalesce(nullif(trim(et.team_name_snapshot), ''), concat('赛事球队#', et.id)), case when coalesce(nullif(trim(et.team_short_name), ''), nullif(trim(t.short_name), '')) is null then case when et.event_team_no is null or trim(et.event_team_no) = '' then '' else concat(' · ', et.event_team_no) end else concat(' · ', coalesce(nullif(trim(et.team_short_name), ''), t.short_name)) end ) as label, concat( coalesce(nullif(trim(s.series_name), ''), '赛事'), ' · ', coalesce(nullif(trim(se.display_title), ''), se.season_name), ' · ', coalesce(nullif(trim(d.division_name), ''), '未分赛区'), ' · ', coalesce(nullif(trim(d.platform_code), ''), '-'), '/',
) as secondaryLabel, et.event_team_status as status, null as memberId, et.source_team_id as teamId, et.id as eventTeamId, null as eventPlayerId, et.team_name_snapshot as teamName, et.event_team_no as playerNo, coalesce(nullif(trim(et.team_short_name), ''), t.short_name) as gameId, d.division_name as divisionName, d.platform_code as platformCode, d.game_mode as gameMode from basket_event_team et left join basket_team t on t.id = et.source_team_id and t.is_delete = 0 left join basket_division d on d.id = et.division_id and d.is_delete = 0 left join basket_season se on se.id = et.season_id and se.is_delete = 0 left join basket_series s on s.id = se.series_id and s.is_delete = 0 where et.is_delete = 0 and et.season_id = #{seasonId}
and ( et.team_name_snapshot like concat('%', #{keyword}, '%') or et.event_team_no like concat('%', #{keyword}, '%') or et.team_short_name like concat('%', #{keyword}, '%') or t.team_name like concat('%', #{keyword}, '%') or t.short_name like concat('%', #{keyword}, '%') or d.division_name like concat('%', #{keyword}, '%') or d.platform_code like concat('%', #{keyword}, '%') )
order by d.sort_order asc, d.id asc, et.team_name_snapshot asc, et.id asc
